import sys

def count_brute(nums, k):
    n = len(nums)
    cnt = 0
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += nums[j]
            if s == k:
                cnt += 1
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = [int(x) for x in data[1:1 + n]]
    k = int(data[1 + n])
    print(count_brute(nums, k))

import sys

def count_opt(nums, k):
    n = len(nums)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + nums[i]
    cnt = 0
    for i in range(n):
        for j in range(i + 1, n + 1):
            if pref[j] - pref[i] == k:
                cnt += 1
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = [int(x) for x in data[1:1 + n]]
    k = int(data[1 + n])
    print(count_opt(nums, k))
